<script setup lang="ts">
import { computed, ref } from 'vue'
const dataset=ref('A'), state=ref('ready'), selected=ref(0)
const labels=['Ride','Power','Endurance','Sprint'], planned=[25,35,40,30]
const actual=computed(()=>dataset.value==='A'?[21,38,32,34]:dataset.value==='B'?[27,31,43,28]:planned)
const delta=(i:number)=>actual.value[i]-planned[i]
const signed=(n:number)=>n>0?'+'+n:''+n
const x=(v:number)=>80+v*4
function reset(){dataset.value='A';state.value='ready';selected.value=0}
</script>
<template>
<section class="dbusage-demo" aria-label="Local dumbbell chart example"><p>Synthetic class attendance. Outline = planned; solid = actual. The connector measures the gap, not a path through time.</p><div class="dbusage-controls"><label>Dataset<select v-model="dataset"><option>A</option><option>B</option><option value="ties">Equal endpoints</option></select></label><label>Data state<select v-model="state"><option value="ready">Ready</option><option value="loading">Loading</option><option value="empty">Empty</option></select></label><button type="button" @click="reset">Reset example</button></div><template v-if="state==='ready'"><div class="dbusage-legend"><span>◯ Planned</span><span>● Actual</span><span>Δ = Actual − Planned</span></div><svg :key="dataset" viewBox="0 0 320 210" role="img" aria-label="Planned and actual attendees on a fixed 0 to 50 scale. Exact values and signed differences are below."><g v-for="tick in [0,25,50]" :key="tick"><line :x1="x(tick)" :x2="x(tick)" y1="20" y2="163" class="dbusage-grid"/><text :x="x(tick)" y="188" text-anchor="middle">{{ tick }}</text></g><g v-for="(v,i) in actual" :key="i" class="dbusage-pair" :class="{selected:selected===i}"><text x="2" :y="39+i*35">{{ labels[i] }}</text><line class="dbusage-gap" :x1="x(planned[i])" :x2="x(v)" :y1="35+i*35" :y2="35+i*35"/><circle class="dbusage-plan" :cx="x(planned[i])" :cy="35+i*35" r="7"/><circle class="dbusage-actual" :cx="x(v)" :cy="35+i*35" r="4"/></g><text x="180" y="207" text-anchor="middle">Attendees · same scale for both endpoints</text></svg><div role="group" aria-label="Select class" class="dbusage-choices"><button v-for="(label,i) in labels" :key="label" type="button" :aria-pressed="selected===i" @click="selected=i" @focus="selected=i">{{ label }}</button></div><p role="status">{{ labels[selected] }}: Planned {{ planned[selected] }}, Actual {{ actual[selected] }}, Δ {{ signed(delta(selected)) }} attendees.</p><table class="dbusage-data"><caption>Exact sample values, dataset {{ dataset }}</caption><thead><tr><th scope="col">Class</th><th scope="col">Plan</th><th scope="col">Actual</th><th scope="col">Δ</th></tr></thead><tbody><tr v-for="(label,i) in labels" :key="label"><th scope="row">{{ label }}</th><td>{{ planned[i] }}</td><td>{{ actual[i] }}</td><td>{{ signed(delta(i)) }}</td></tr></tbody></table></template><p v-else role="status" class="dbusage-state">{{ state==='loading'?'Loading demonstration only; no request is running. Values are withheld.':'No sample pairs in this state. Choose Ready to recover.' }}</p></section>
</template>
